import './App.css';

function OrgName() {
  return (
    <input
      type="text"
      id="orgname"
      placeholder="Enter Organization Name"
    />
  );
}

function AdminName() {
  return (
    <input
      type="text"
      id="adminname"
      placeholder="Enter Administrator Name"
    />
  );
}

export default function MyApp() {
  return (
    <div>
      <div className="OrgNameGroup">
        <label htmlFor="orgname" id="orgnametext">Organization Name</label>
        <OrgName />
      </div>

      <div className="AdminNameGroup">
        <label htmlFor="adminname" id="adminnametext">Admin</label>
        <AdminName />
      </div>
    </div>
  );
}
